package com.adaptivelearning.goalproject.domain;import com.adaptivelearning.shared.exception.*;import org.junit.jupiter.api.Test;import java.util.List;import static org.assertj.core.api.Assertions.*;
class DependencyGraphPolicyTest {@Test void detectsThreeNodeCycle(){var edges=List.of(new DependencyGraphPolicy.Edge(1,2),new DependencyGraphPolicy.Edge(2,3),new DependencyGraphPolicy.Edge(3,1));assertThatThrownBy(()->DependencyGraphPolicy.requireAcyclic(edges)).isInstanceOf(BusinessException.class).extracting(e->((BusinessException)e).getCode()).isEqualTo(ErrorCode.DEPENDENCY_CYCLE_DETECTED);}@Test void acceptsDag(){assertThatCode(()->DependencyGraphPolicy.requireAcyclic(List.of(new DependencyGraphPolicy.Edge(1,2),new DependencyGraphPolicy.Edge(1,3),new DependencyGraphPolicy.Edge(2,4)))).doesNotThrowAnyException();}}
